function fetchJSON(url, ms){
  const ctl = new AbortController(); const tm = setTimeout(() => ctl.abort(), ms);
  return fetch(url, {signal: ctl.signal, headers: {'User-Agent': 'FootLetter/1.0 (jeu de quiz foot; netlify)'}})
    .then(r => { clearTimeout(tm); if(!r.ok) throw new Error('http'); return r.json(); });
}

/* ================= BASE DE JOUEURS ================= */
const MAX_PLAYERS=10;
const PARTICLES=new Set(['van','von','de','da','di','del','della','der','den','dos','das','do','du','la','le','el','al','ten','ter','mac','dal','degli']);
function norm(s){
  return String(s).toLowerCase()
    .replace(/ø/g,'o').replace(/æ/g,'ae').replace(/œ/g,'oe').replace(/ß/g,'ss').replace(/ł/g,'l').replace(/đ/g,'d').replace(/ı/g,'i').replace(/ð/g,'d').replace(/þ/g,'th')
    .normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
}
const P=[], IDX=new Map(), FIRST=new Set();
(function build(){
  const raw=RAW_PLAYERS, seen=new Set();
  raw.split('\n').forEach(line=>{
    line=line.trim(); if(!line||line[0]==='#'||line.startsWith('/*')) return;
    const parts=line.split('|'), name=parts[0].trim(), full=norm(name);
    if(!full||seen.has(full)) return; seen.add(full);
    const id=P.length, toks=name.split(/\s+/), keys=new Set([full]), letters=new Set();
    if(toks.length===1) letters.add(full[0]);
    else{
      FIRST.add(norm(toks[0]));
      const sur=toks.slice(1), s1=norm(sur.join(' '));
      if(s1){ keys.add(s1); letters.add(s1[0]); }
      let i=0; while(i<sur.length-1&&PARTICLES.has(norm(sur[i]))) i++;
      if(i>0){ const s2=norm(sur.slice(i).join(' ')); keys.add(s2); letters.add(s2[0]); }
    }
    parts.slice(1).forEach(a=>{
      const n=norm(a); if(!n) return; keys.add(n);
      const at=a.trim().split(/\s+/);
      if(at.length===1) letters.add(n[0]);
      else{ let j=1; while(j<at.length-1&&PARTICLES.has(norm(at[j]))) j++; const s=norm(at.slice(j).join(' ')); if(s) letters.add(s[0]); }
    });
    P.push({name,letters,full,sur:toks.length>1?norm(toks.slice(1).join(' ')):full});
    keys.forEach(k=>{ let arr=IDX.get(k); if(!arr){ arr=[]; IDX.set(k,arr); } if(!arr.includes(id)) arr.push(id); });
  });
})();
const LETTER_COUNT={};
P.forEach(p=>p.letters.forEach(l=>{ if(/[a-z]/.test(l)) LETTER_COUNT[l]=(LETTER_COUNT[l]||0)+1; }));
const DRAW_LETTERS=Object.keys(LETTER_COUNT).filter(l=>LETTER_COUNT[l]>=20).sort();
const DAILY_LETTERS=Object.keys(LETTER_COUNT).filter(l=>LETTER_COUNT[l]>=55).sort();
const ALL_LETTERS='abcdefghijklmnopqrstuvwxyz'.split('');
const IDX_BY_LETTER=new Map();
IDX.forEach((arr,k)=>{ let m=IDX_BY_LETTER.get(k[0]); if(!m){ m=[]; IDX_BY_LETTER.set(k[0],m); } m.push(k); });

function lev(a,b,max){
  if(Math.abs(a.length-b.length)>max) return max+1;
  let prev=Array.from({length:b.length+1},(_,i)=>i);
  for(let i=1;i<=a.length;i++){
    const cur=[i]; let rowMin=i;
    for(let j=1;j<=b.length;j++){ const c=Math.min(prev[j]+1,cur[j-1]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1)); cur.push(c); if(c<rowMin) rowMin=c; }
    if(rowMin>max) return max+1; prev=cur;
  }
  return prev[b.length];
}
function lookup(n){
  if(IDX.get(n)) return {ids:[...IDX.get(n)],key:n,fuzzy:false};
  const tol=n.length>=10?2:n.length>=5?1:0;
  if(!tol) return {ids:[],key:n};
  let best=[],bd=tol+1,bk=n;
  for(const k of (IDX_BY_LETTER.get(n[0])||[])){ const d=lev(k,n,tol); if(d<bd){ bd=d; best=[...IDX.get(k)]; bk=k; } }
  return bd<=tol?{ids:best,key:bk,fuzzy:true}:{ids:[],key:n};
}
function titleCase(s){ return String(s).trim().replace(/\s+/g,' ').slice(0,40).split(' ').map(w=>w?w[0].toUpperCase()+w.slice(1):w).join(' '); }
function nameLetters(n){ const tk=n.split(' '), L=new Set([tk[0][0]]); let i=0; while(i<tk.length-1&&PARTICLES.has(tk[i])) i++; L.add(tk[i][0]); return L; }
function fullNameLetters(n){ const tk=n.split(' '); if(tk.length<2||PARTICLES.has(tk[0])) return nameLetters(n); return nameLetters(tk.slice(1).join(' ')); }
function surKey(id){ const tk=P[id].name.split(/\s+/); return tk.length>1?norm(tk.slice(1).join(' ')):norm(tk[0]); }
function surDisplay(id,n){ const tk=P[id].name.split(/\s+/); for(let j=0;j<tk.length;j++){ const c=tk.slice(j).join(' '); if(norm(c)===n) return c; } return null; }

/* Vérification locale : {st:'ok',display,keys} | {st:'bad',c,x,count} | {st:'unknown',n} */
function checkLocal(input,letter,used){
  const n=norm(input), l=letter.toLowerCase();
  if(n.length<2) return {st:'bad',c:'short',count:false};
  if(!IDX.get(n)&&FIRST.has(n)) return {st:'bad',c:'first',x:titleCase(input),count:true};
  const r=lookup(n);
  if(r.ids.length){
    const k=r.key;
    const fullHit=r.ids.filter(i=>P[i].full===k&&P[i].name.includes(' '));
    const pool=fullHit.length?fullHit:r.ids;
    const withL=pool.filter(i=>(P[i].full===k&&P[i].name.includes(' '))?nameLetters(P[i].sur).has(l):nameLetters(k).has(l));
    if(!withL.length){ if(r.fuzzy) return {st:'unknown',n}; return {st:'bad',c:'letter',x:P[pool[0]].name,count:true}; }
    let display,keys;
    const exactFull=withL.filter(i=>P[i].full===k);
    if(exactFull.length===1||withL.length===1){
      const id=exactFull.length===1?exactFull[0]:withL[0];
      display=P[id].name; keys=['f:'+P[id].full];
      if(P[id].full!==k) keys.push('s:'+k);
      else{ const sk=surKey(id); if((IDX.get(sk)||[]).length===1) keys.push('s:'+sk); }
    } else { display=surDisplay(withL[0],k)||titleCase(input); keys=['s:'+k]; }
    if(keys.some(x=>used.has(x))) return {st:'bad',c:'dup',x:display,count:true};
    return {st:'ok',display,keys};
  }
  if(!nameLetters(n).has(l)&&!fullNameLetters(n).has(l)) return {st:'bad',c:'letter2',x:titleCase(input),count:true};
  return {st:'unknown',n};
}
function parisDate(d){ try{ return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(d||new Date()); }catch(_){ return (d||new Date()).toISOString().slice(0,10); } }
function hash(s){ let h=2166136261; for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619); } return h>>>0; }
function dailyLetter(date){
  const pick=dt=>DAILY_LETTERS[hash('footletter:'+dt)%DAILY_LETTERS.length];
  let l=pick(date);
  const y=parisDate(new Date(new Date(date+'T12:00:00Z').getTime()-86400000));
  if(l===pick(y)) l=DAILY_LETTERS[(DAILY_LETTERS.indexOf(l)+1)%DAILY_LETTERS.length];
  return l.toUpperCase();
}


const WD='https://www.wikidata.org/w/api.php?format=json&origin=*&';
function wdSearch(text,limit,extra){
  const q=`haswbstatement:P106=Q937857 haswbstatement:P21=Q6581097 ${extra||''} ${String(text).trim().slice(0,60)}`;
  return fetchJSON(WD+'action=query&list=search&srlimit='+limit+'&srsearch='+encodeURIComponent(q),7000)
    .then(r=>((r.query&&r.query.search)||[]).map(x=>x.title).filter(x=>/^Q\d+$/.test(x)));
}
function wdEntities(ids,props,langs){ return fetchJSON(WD+'action=wbgetentities&props='+props+(langs?'&languages='+langs:'')+'&ids='+ids.join('|'),7000).then(r=>r.entities||{}); }
const NOT_WP=/^(commons|species|meta|wikidata|mediawiki|sources|outreach|incubator|wikimania|foundation)wiki$/;
function wpCount(e){ return Object.keys(e.sitelinks||{}).filter(k=>/wiki$/.test(k)&&!NOT_WP.test(k)).length; }
const WD_SEARCH=new Map();
// Recherche d'un nom parmi les footballeurs pros (au moins un club et 2 articles Wikipédia)
function wikiLookup(input){
  const n=norm(input);
  if(WD_SEARCH.has(n)) return WD_SEARCH.get(n);
  const pr=(async()=>{
    const ids=(await wdSearch(input,20,'haswbstatement:P54')).slice(0,20);
    if(!ids.length) return {hits:[]};
    const ents=await wdEntities(ids,'labels|aliases|sitelinks','fr|en|de|es|pt|it|nl');
    const hits=[];
    ids.forEach(id=>{
      const e=ents[id]; if(!e||!e.labels) return;
      if(wpCount(e)<2) return;
      const names=[...Object.values(e.labels).map(x=>x.value),...Object.values(e.aliases||{}).flat().map(x=>x.value)];
      const label=(e.labels.fr||e.labels.en||Object.values(e.labels)[0]||{}).value||'';
      let type=null;
      for(const nm of names){ const x=norm(nm); if(x===n){ type=x.includes(' ')?'full':'mono'; break; } if(x.endsWith(' '+n)) type='sur'; }
      if(type&&label) hits.push({id,label,type});
    });
    return {hits};
  })().catch(()=>({error:true,hits:[]}));
  WD_SEARCH.set(n,pr); pr.then(v=>{ if(v.error) WD_SEARCH.delete(n); });
  return pr;
}
// Résolution complète d'une réponse inconnue en local
async function resolveRemote(text,letter,used){
  const n=norm(text), l=letter.toLowerCase(), res=await wikiLookup(text);
  if(res.error) return {st:'none',off:1};
  const hits=res.hits.filter(h=>h.type==='full'?fullNameLetters(n).has(l):nameLetters(n).has(l));
  if(!hits.length) return res.hits.length?{st:'bad',c:'letter2',x:titleCase(text),count:true}:{st:'none'};
  let display,keys;
  const fulls=hits.filter(h=>h.type!=='sur');
  if(hits.length===1||fulls.length===1){ const h=fulls.length===1?fulls[0]:hits[0]; display=h.label; keys=['f:'+norm(h.label)]; if(norm(h.label)!==n) keys.push('s:'+n); }
  else { display=titleCase(text); keys=[(n.includes(' ')?'f:':'s:')+n]; }
  if(keys.some(k=>used.has(k))) return {st:'bad',c:'dup',x:display,count:true};
  return {st:'ok',display,keys};
}

export { norm, titleCase, checkLocal, nameLetters, fullNameLetters, resolveRemote, DRAW_LETTERS, DAILY_LETTERS, ALL_LETTERS, parisDate, dailyLetter, P };
